source='''from collections import deque

def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    seen5 = set()
    components = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 5 or (r, c) in seen5:
                continue
            q = deque([(r, c)])
            seen5.add((r, c))
            comp = []
            while q:
                x, y = q.popleft(); comp.append((x, y))
                for nx, ny in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
                    if 0 <= nx < h and 0 <= ny < w and grid[nx][ny] == 5 and (nx,ny) not in seen5:
                        seen5.add((nx,ny)); q.append((nx,ny))
            components.append(comp)

    for line in components:
        rs = [p[0] for p in line]; cs = [p[1] for p in line]
        vertical = len(set(cs)) == 1
        line_cells = set(line)
        adjacent = set()
        for r, c in line:
            for nr, nc in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
                if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] not in (0,5):
                    adjacent.add((nr,nc))
        seen = set()
        for start in adjacent:
            if start in seen: continue
            q = deque([start]); seen.add(start); seed=[]
            while q:
                x,y=q.popleft(); seed.append((x,y))
                for nx,ny in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
                    if 0 <= nx < h and 0 <= ny < w and grid[nx][ny] not in (0,5) and (nx,ny) not in seen:
                        seen.add((nx,ny)); q.append((nx,ny))
            sr=[p[0] for p in seed]; sc=[p[1] for p in seed]
            r0,r1=min(sr),max(sr); c0,c1=min(sc),max(sc)
            if vertical:
                # Repeat the colored row-pattern along the 5-line.
                for r in range(min(rs), max(rs)+1):
                    template_r = r0 + ((r-r0) % (r1-r0+1))
                    for c in range(c0,c1+1):
                        if grid[template_r][c] not in (0,5): out[r][c]=grid[template_r][c]
            else:
                # Repeat the colored column-pattern across the 5-line.
                # Use the seed column nearest the attached 5 segment.
                attach_c = min(sc, key=lambda x: min(abs(x-y) for y in cs))
                for c in range(min(cs), max(cs)+1):
                    for r in range(r0,r1+1):
                        if grid[r][attach_c] not in (0,5): out[r][c]=grid[r][attach_c]
    return out
'''
